-- ============================================================
-- base64 + carregador de texturas
-- ============================================================
local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local B64MAP = {}
for i = 1, 64 do
	B64MAP[B64:byte(i)] = i - 1
end

local function b64decode(s)
	local out, n = {}, 0
	local bits, nb = 0, 0
	for i = 1, #s do
		local v = B64MAP[s:byte(i)]
		if v then
			bits = bits * 64 + v
			nb = nb + 6
			if nb >= 8 then
				nb = nb - 8
				local p = 2 ^ nb
				local byte = math.floor(bits / p)
				bits = bits - byte * p
				n = n + 1
				out[n] = string.char(byte)
			end
		end
	end
	return table.concat(out)
end

local getasset = getcustomasset or getsynasset
local FOLDER = "OreUI_Assets"
local canFile = (writefile ~= nil) and (getasset ~= nil)
if canFile then
	pcall(function()
		if makefolder and isfolder and not isfolder(FOLDER) then
			makefolder(FOLDER)
		end
	end)
end

local assetCache = {}
local function asset(hash)
	local c = assetCache[hash]
	if c ~= nil then
		return c
	end
	local res = false
	if canFile then
		local ok, id = pcall(function()
			local path = FOLDER .. "/" .. hash .. ".png"
			local need = true
			if isfile then
				need = not isfile(path)
			end
			if need then
				writefile(path, b64decode(PNG[hash]))
			end
			return getasset(path)
		end)
		if ok and id and id ~= "" then
			res = id
		end
	end
	assetCache[hash] = res
	return res
end

OreUI.TexturesAvailable = canFile

-- ============================================================
-- Helpers de instância
-- ============================================================
local function new(class, props, parent)
	local o = Instance.new(class)
	if props then
		for k, v in pairs(props) do
			o[k] = v
		end
	end
	if parent then
		o.Parent = parent
	end
	return o
end

local function setFont(o, f)
	if typeof(f) == "Font" then
		o.FontFace = f
	else
		o.Font = f
	end
end

local function label(parent, text, o)
	o = o or {}
	local l = new("TextLabel", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Text = text or "",
		TextColor3 = o.Color or WHITE,
		TextSize = o.TextSize or Theme.TextSize,
		TextXAlignment = o.X or Enum.TextXAlignment.Left,
		TextYAlignment = o.Y or Enum.TextYAlignment.Center,
		TextWrapped = o.Wrap or false,
		RichText = o.RichText or false,
		Size = o.Size or UDim2.new(1, 0, 1, 0),
		Position = o.Position or UDim2.new(),
	})
	setFont(l, o.Font or Theme.Font)
	if o.Auto then
		l.AutomaticSize = Enum.AutomaticSize.Y
	end
	l.Parent = parent
	return l
end

local function hitbox(parent)
	return new("TextButton", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Text = "",
		AutoButtonColor = false,
		Size = UDim2.new(1, 0, 1, 0),
	}, parent)
end

-- Troca a textura de um ImageLabel (9-slice quando existir) ou usa o fallback de cores.
local function setSkin(img, path, linear)
	local t = TEX[path]
	if not t then
		return
	end
	local id = asset(t.h)
	local stroke = img:FindFirstChild("_s")
	img.ResampleMode = linear and Enum.ResamplerMode.Default or Enum.ResamplerMode.Pixelated
	if id then
		img.Image = id
		img.BackgroundTransparency = 1
		if stroke then
			stroke.Enabled = false
		end
		if t.s then
			img.ScaleType = Enum.ScaleType.Slice
			img.SliceCenter = Rect.new(t.s[1], t.s[2], t.w - t.s[3], t.ht - t.s[4])
		else
			img.ScaleType = Enum.ScaleType.Stretch
		end
	else
		img.Image = ""
		local f, e = t.f, t.e
		img.BackgroundColor3 = Color3.fromRGB(f[1], f[2], f[3])
		img.BackgroundTransparency = 1 - f[4] / 255
		if stroke then
			if t.s and e[4] > 0 then
				stroke.Color = Color3.fromRGB(e[1], e[2], e[3])
				stroke.Enabled = true
			else
				stroke.Enabled = false
			end
		end
	end
end

local function skin(parent, path, props, linear)
	local img = new("ImageLabel", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Image = "",
		Size = UDim2.new(1, 0, 1, 0),
	})
	if props then
		for k, v in pairs(props) do
			img[k] = v
		end
	end
	new("UIStroke", {
		Name = "_s",
		Thickness = 1,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Enabled = false,
	}, img)
	setSkin(img, path, linear)
	img.Parent = parent
	return img
end

local function spawnCb(cb, ...)
	if cb then
		task.spawn(cb, ...)
	end
end

local function autoScale(size)
	local cam = workspace.CurrentCamera
	local vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
	local s = math.min((vp.X - 24) / size.X, (vp.Y - 24) / size.Y)
	s = math.floor(s * 2) / 2
	return math.clamp(s, 1, 2)
end

local function guiParent()
	local ok, h = pcall(function()
		return gethui and gethui()
	end)
	if ok and h then
		return h
	end
	local ok2, cg = pcall(function()
		return game:GetService("CoreGui")
	end)
	if ok2 and cg then
		local t = Instance.new("Folder")
		local ok3 = pcall(function()
			t.Parent = cg
		end)
		t:Destroy()
		if ok3 then
			return cg
		end
	end
	return Players.LocalPlayer:WaitForChild("PlayerGui")
end

-- ============================================================
-- Container (base de Window, Page, Card, Row...) — todos os componentes
-- ============================================================
local Container = {}
Container.__index = Container

local function newContainer(parentContainer, content, cols)
	return setmetatable({
		Lib = parentContainer.Lib,
		Win = parentContainer.Win,
		Scroll = parentContainer.Scroll,
		Content = content,
		Cols = cols or 1,
		_n = 0,
	}, Container)
end

function Container:_width(h)
	local c = self.Cols
	if c <= 1 then
		return UDim2.new(1, 0, 0, h)
	end
	local gap = Theme.Gap
	return UDim2.new(1 / c, -math.ceil(gap * (c - 1) / c), 0, h)
end

function Container:_holder(h, w)
	self._n = self._n + 1
	local size = w and UDim2.new(0, w, 0, h) or self:_width(h)
	return new("Frame", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = size,
		LayoutOrder = self._n,
	}, self.Content)
end

local function elem(holder, e)
	e = e or {}
	e.Frame = holder
	function e:Destroy()
		holder:Destroy()
	end
	function e:SetVisible(v)
		holder.Visible = v
	end
	return e
end

local function listLayout(parent, pad, horizontal)
	return new("UIListLayout", {
		Padding = UDim.new(0, pad),
		SortOrder = Enum.SortOrder.LayoutOrder,
		FillDirection = horizontal and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical,
	}, parent)
end

-- ---------- Label / Divider / Space ----------
function Container:Label(o)
	if type(o) == "string" then
		o = { Text = o }
	end
	o = o or {}
	self._n = self._n + 1
	local l = label(self.Content, o.Text or "", {
		Color = o.Color or (o.Muted and MUTED) or WHITE,
		Size = UDim2.new(1, 0, 0, 0),
		Wrap = true,
		Auto = true,
		RichText = o.RichText,
		TextSize = o.TextSize,
		Font = o.Font,
		X = o.Align,
	})
	l.LayoutOrder = self._n
	local e = elem(l)
	function e:Set(t)
		l.Text = t
	end
	function e:Get()
		return l.Text
	end
	e.Label = l
	return e
end

function Container:Title(text)
	return self:Label({ Text = text, Font = Theme.TitleFont, TextSize = Theme.TitleSize })
end

function Container:Divider(o)
	o = o or {}
	local holder = self:_holder(6)
	local variant = o.Variant or "default"
	skin(holder, "divider/horizontal/" .. variant, {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 0, 0.5, 0),
		Size = UDim2.new(1, 0, 0, 2),
	})
	return elem(holder)
end

function Container:Space(n)
	return elem(self:_holder(n or 4))
end

-- ---------- Button ----------
local BUTTONS = {}
for _, v in ipairs({ "primary", "secondary", "contrast", "danger", "realm" }) do
	BUTTONS[v] = {
		d = "button/" .. v .. "/background",
		h = "button/" .. v .. "/background_hover",
		p = "button/" .. v .. "/background_pressed",
		x = "button/disabled/background",
		c = WHITE,
		dc = DISABLED,
	}
end
BUTTONS.secondary.c = BLACK
BUTTONS.contrast.dc = MUTED
BUTTONS.hero = {
	d = BUTTONS.primary.d, h = BUTTONS.primary.h, p = BUTTONS.primary.p, x = BUTTONS.primary.x,
	c = WHITE, dc = DISABLED, hero = true,
}
BUTTONS.transparent = {
	d = "button/transparent/background", h = "button/transparent/background_hover",
	p = "button/transparent/background_pressed", x = "button/transparent/background",
	c = WHITE, dc = DISABLED,
}

function Container:Button(o)
	o = o or {}
	local V = BUTTONS[o.Variant or "primary"] or BUTTONS.primary
	local holder = self:_holder(o.Height or 20, o.Width)
	local img = skin(holder, V.d)
	local txt = label(img, o.Text or "Button", {
		Color = V.c,
		X = Enum.TextXAlignment.Center,
		Size = UDim2.new(1, -8, 1, -3),
		Position = UDim2.fromOffset(4, 0),
		Font = V.hero and Theme.TitleFont or Theme.Font,
		TextSize = V.hero and Theme.TitleSize or Theme.TextSize,
	})
	local hit = hitbox(holder)
	local st = { hover = false, down = false, enabled = o.Enabled ~= false }
	local function refresh()
		local path = (not st.enabled and V.x) or (st.down and V.p) or (st.hover and V.h) or V.d
		setSkin(img, path)
		txt.TextColor3 = st.enabled and V.c or V.dc
		txt.Position = UDim2.fromOffset(4, (st.down and st.enabled) and 1 or 0)
	end
	refresh()
	hit.MouseEnter:Connect(function()
		st.hover = true
		refresh()
	end)
	hit.MouseLeave:Connect(function()
		st.hover, st.down = false, false
		refresh()
	end)
	hit.MouseButton1Down:Connect(function()
		st.down = true
		refresh()
	end)
	hit.MouseButton1Up:Connect(function()
		st.down = false
		if UIS.TouchEnabled then
			st.hover = false
		end
		refresh()
	end)
	hit.Activated:Connect(function()
		if st.enabled then
			spawnCb(o.Callback)
		end
	end)
	local e = elem(holder)
	function e:SetText(t)
		txt.Text = t
	end
	function e:SetEnabled(v)
		st.enabled = v and true or false
		refresh()
	end
	return e
end

-- ---------- Toggle / Checkbox / Radio ----------
local SWITCH = {
	toggle = { on = "toggle/on", off = "toggle/off", w = 27, h = 14, row = 18, right = true },
	checkbox = { on = "checkbox/checked", off = "checkbox/unchecked", w = 12, h = 12, row = 16 },
	radio = { on = "radio/selected", off = "radio/unselected", w = 12, h = 12, row = 16, linear = true },
}

local function switchInto(holder, kind, o, onChange)
	local C = SWITCH[kind]
	local st = { value = o.Default and true or false, hover = false, enabled = o.Enabled ~= false }
	local img = skin(holder, C.off, {
		AnchorPoint = Vector2.new(C.right and 1 or 0, 0.5),
		Position = UDim2.new(C.right and 1 or 0, 0, 0.5, 0),
		Size = UDim2.fromOffset(C.w, C.h),
	}, C.linear)
	local lbl = label(holder, o.Text or "", {
		Position = UDim2.fromOffset(C.right and 0 or (C.w + 4), 0),
		Size = UDim2.new(1, -(C.w + 4), 1, 0),
	})
	local hit = hitbox(holder)
	local function refresh()
		local base = st.value and C.on or C.off
		local suffix = (not st.enabled and "_disabled") or (st.hover and "_hover") or ""
		setSkin(img, base .. suffix, C.linear)
		lbl.TextColor3 = st.enabled and WHITE or DISABLED
	end
	refresh()
	hit.MouseEnter:Connect(function()
		st.hover = true
		refresh()
	end)
	hit.MouseLeave:Connect(function()
		st.hover = false
		refresh()
	end)
	hit.Activated:Connect(function()
		if not st.enabled then
			return
		end
		if kind == "radio" and st.value then
			return
		end
		st.value = not st.value
		if UIS.TouchEnabled then
			st.hover = false
		end
		refresh()
		onChange(st.value)
	end)
	local e = elem(holder)
	function e:Get()
		return st.value
	end
	function e:Set(v, silent)
		st.value = v and true or false
		refresh()
		if not silent then
			onChange(st.value)
		end
	end
	function e:SetEnabled(v)
		st.enabled = v and true or false
		refresh()
	end
	return e
end

function Container:Toggle(o)
	o = o or {}
	local holder = self:_holder(SWITCH.toggle.row, o.Width)
	return switchInto(holder, "toggle", o, function(v)
		spawnCb(o.Callback, v)
	end)
end

function Container:Checkbox(o)
	o = o or {}
	local holder = self:_holder(SWITCH.checkbox.row, o.Width)
	return switchInto(holder, "checkbox", o, function(v)
		spawnCb(o.Callback, v)
	end)
end

function Container:Radio(o)
	o = o or {}
	local opts = o.Options or {}
	self._n = self._n + 1
	local group = new("Frame", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		LayoutOrder = self._n,
	}, self.Content)
	listLayout(group, 2)
	local order = 0
	if o.Text then
		order = order + 1
		local l = label(group, o.Text, { Size = UDim2.new(1, 0, 0, 11) })
		l.LayoutOrder = order
	end
	local items, current = {}, o.Default
	local function choose(name, silent)
		current = name
		for n, it in pairs(items) do
			it:Set(n == name, true)
		end
		if not silent then
			spawnCb(o.Callback, name)
		end
	end
	for _, name in ipairs(opts) do
		order = order + 1
		local row = new("Frame", {
			BackgroundTransparency = 1, BorderSizePixel = 0,
			Size = UDim2.new(1, 0, 0, SWITCH.radio.row), LayoutOrder = order,
		}, group)
		items[name] = switchInto(row, "radio", { Text = tostring(name), Default = name == current, Enabled = o.Enabled }, function()
			choose(name)
		end)
	end
	local e = elem(group)
	function e:Get()
		return current
	end
	function e:Set(name, silent)
		choose(name, silent)
	end
	return e
end

-- ---------- Slider ----------
function Container:Slider(o)
	o = o or {}
	local min, max = o.Min or 0, o.Max or 100
	local step = o.Step or 1
	local value = math.clamp(o.Default or min, min, max)
	local suffix = o.Suffix or ""
	local holder = self:_holder(31, o.Width)
	local lbl = label(holder, o.Text or "", { Size = UDim2.new(1, 0, 0, 10) })
	local val = label(holder, "", { Size = UDim2.new(1, 0, 0, 10), X = Enum.TextXAlignment.Right, Color = MUTED })
	local bar = new("Frame", {
		BackgroundTransparency = 1, BorderSizePixel = 0,
		Position = UDim2.fromOffset(8, 11), Size = UDim2.new(1, -16, 0, 20),
	}, holder)
	skin(bar, "slider/track", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, -8, 0.5, 0), Size = UDim2.new(1, 16, 0, 6) })
	local prog = skin(bar, "slider/progress", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, -8, 0.5, 0), Size = UDim2.new(0, 0, 0, 6) })
	local thumb = skin(bar, "slider/thumb", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(16, 16) })
	local hit = hitbox(holder)
	local st = { enabled = o.Enabled ~= false, dragging = false, hover = false }

	local function fmt(v)
		if step >= 1 then
			return tostring(math.floor(v + 0.5))
		end
		local dec = math.max(0, math.ceil(-math.log10(step)))
		return string.format("%." .. dec .. "f", v)
	end
	local function render()
		local f = (max == min) and 0 or (value - min) / (max - min)
		thumb.Position = UDim2.new(f, 0, 0.5, 0)
		prog.Size = UDim2.new(f, 8, 0, 6)
		prog.Visible = f > 0.02
		val.Text = fmt(value) .. suffix
		local dis = not st.enabled
		setSkin(prog, dis and "slider/progress_disabled" or "slider/progress")
		setSkin(thumb, dis and "slider/thumb_disabled" or ((st.hover or st.dragging) and "slider/thumb_hover" or "slider/thumb"))
		lbl.TextColor3 = dis and DISABLED or WHITE
		val.TextColor3 = dis and DISABLED or MUTED
	end
	local function setFromX(x, silent)
		local w = bar.AbsoluteSize.X
		if w <= 0 then
			return
		end
		local f = math.clamp((x - bar.AbsolutePosition.X) / w, 0, 1)
		local v = min + f * (max - min)
		v = math.clamp(math.floor((v - min) / step + 0.5) * step + min, min, max)
		if v ~= value then
			value = v
			render()
			if not silent then
				spawnCb(o.Callback, value)
			end
		end
	end
	render()
	hit.MouseEnter:Connect(function()
		st.hover = true
		render()
	end)
	hit.MouseLeave:Connect(function()
		st.hover = false
		render()
	end)
	hit.InputBegan:Connect(function(i)
		if not st.enabled then
			return
		end
		if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
			st.dragging = true
			if self.Scroll then
				self.Scroll.ScrollingEnabled = false
			end
			setFromX(i.Position.X)
			render()
		end
	end)
	local lib = self.Lib
	lib:_connect(UIS.InputChanged, function(i)
		if st.dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
			setFromX(i.Position.X)
		end
	end)
	lib:_connect(UIS.InputEnded, function(i)
		if st.dragging and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then
			st.dragging = false
			if self.Scroll then
				self.Scroll.ScrollingEnabled = true
			end
			render()
		end
	end)
	local e = elem(holder)
	function e:Get()
		return value
	end
	function e:Set(v, silent)
		value = math.clamp(v, min, max)
		render()
		if not silent then
			spawnCb(o.Callback, value)
		end
	end
	function e:SetEnabled(v)
		st.enabled = v and true or false
		render()
	end
	return e
end

-- ---------- Input (campo de texto) ----------
function Container:Input(o)
	o = o or {}
	local lblH = o.Text and 11 or 0
	local holder = self:_holder(lblH + 22, o.Width)
	if o.Text then
		label(holder, o.Text, { Size = UDim2.new(1, 0, 0, 10) })
	end
	local field = skin(holder, "field/background", { Position = UDim2.fromOffset(0, lblH), Size = UDim2.new(1, 0, 0, 22) })
	local box = new("TextBox", {
		BackgroundTransparency = 1, BorderSizePixel = 0,
		Position = UDim2.fromOffset(6, 5), Size = UDim2.new(1, -12, 1, -8),
		Text = o.Default or "", PlaceholderText = o.Placeholder or "",
		PlaceholderColor3 = MUTED, TextColor3 = WHITE, TextSize = Theme.TextSize,
		TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false,
		TextEditable = o.Enabled ~= false,
	}, field)
	setFont(box, Theme.Font)
	local enabled = o.Enabled ~= false
	local function paint(hover)
		setSkin(field, (not enabled and "field/background_disabled") or (hover and "field/background_hover") or "field/background")
		box.TextColor3 = enabled and WHITE or DISABLED
	end
	box.MouseEnter:Connect(function()
		paint(true)
	end)
	box.MouseLeave:Connect(function()
		paint(false)
	end)
	box.FocusLost:Connect(function(enter)
		if o.Numeric then
			local n = tonumber(box.Text)
			box.Text = n and tostring(n) or (o.Default or "")
		end
		spawnCb(o.Callback, box.Text, enter)
	end)
	local e = elem(holder)
	function e:Get()
		return box.Text
	end
	function e:Set(t)
		box.Text = tostring(t)
	end
	function e:SetEnabled(v)
		enabled = v and true or false
		box.TextEditable = enabled
		paint(false)
	end
	e.TextBox = box
	return e
end

-- ---------- Dropdown ----------
function Container:Dropdown(o)
	o = o or {}
	local opts = o.Options or {}
	local lblH = o.Text and 11 or 0
	local holder = self:_holder(lblH + 22, o.Width)
	if o.Text then
		label(holder, o.Text, { Size = UDim2.new(1, 0, 0, 10) })
	end
	local face = skin(holder, "dropdown/background", { Position = UDim2.fromOffset(0, lblH), Size = UDim2.new(1, 0, 0, 22) })
	local txt = label(face, "", { Color = BLACK, Position = UDim2.fromOffset(6, 0), Size = UDim2.new(1, -22, 1, -3) })
	local arrow = skin(face, "dropdown/arrow", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -7, 0.5, -1), Size = UDim2.fromOffset(7, 4) })
	local hit = hitbox(face)
	local st = { value = o.Default or opts[1], enabled = o.Enabled ~= false, hover = false }
	local function paint()
		txt.Text = st.value ~= nil and tostring(st.value) or (o.Placeholder or "")
		setSkin(face, (not st.enabled and "dropdown/background_disabled") or (st.hover and "dropdown/background_hover") or "dropdown/background")
		setSkin(arrow, st.enabled and "dropdown/arrow" or "dropdown/arrow_disabled")
		txt.TextColor3 = st.enabled and BLACK or DISABLED
	end
	paint()
	local function set(v, silent)
		st.value = v
		paint()
		if not silent then
			spawnCb(o.Callback, v)
		end
	end
	local function open()
		local win = self.Win
		if win._closePopup then
			win._closePopup()
		end
		local sc = win.UIScale.Scale
		local rel = (face.AbsolutePosition - win.Frame.AbsolutePosition) / sc
		local w = face.AbsoluteSize.X / sc
		local rowH = 16
		local rows = math.min(#opts, 6)
		local h = rows * (rowH + 1) + 5
		local y = rel.Y + 21
		if y + h > win.Frame.AbsoluteSize.Y / sc then
			y = rel.Y - h + 1
		end
		local catcher = new("TextButton", {
			BackgroundTransparency = 1, Text = "", AutoButtonColor = false, Size = UDim2.new(1, 0, 1, 0),
		}, win.Overlay)
		local pop = skin(catcher, "dropdown/popup", { Position = UDim2.fromOffset(rel.X, y), Size = UDim2.fromOffset(w, h) })
		local list = new("ScrollingFrame", {
			BackgroundTransparency = 1, BorderSizePixel = 0,
			Position = UDim2.fromOffset(2, 2), Size = UDim2.new(1, -4, 1, -4),
			CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
			ScrollBarThickness = 2, ScrollBarImageColor3 = MUTED,
			ScrollingDirection = Enum.ScrollingDirection.Y, ElasticBehavior = Enum.ElasticBehavior.Never,
		}, pop)
		listLayout(list, 1)
		local function close()
			win._closePopup = nil
			catcher:Destroy()
		end
		win._closePopup = close
		catcher.Activated:Connect(close)
		for i, name in ipairs(opts) do
			local selected = name == st.value
			local base = selected and "dropdown/option/background_selected" or "dropdown/option/background"
			local row = skin(list, base, { Size = UDim2.new(1, 0, 0, rowH) })
			row.LayoutOrder = i
			label(row, tostring(name), { Position = UDim2.fromOffset(5, 0), Size = UDim2.new(1, -10, 1, 0), Color = selected and SUCCESS or WHITE })
			local rb = hitbox(row)
			rb.MouseEnter:Connect(function()
				setSkin(row, "dropdown/option/background_hover")
			end)
			rb.MouseLeave:Connect(function()
				setSkin(row, base)
			end)
			rb.Activated:Connect(function()
				close()
				set(name)
			end)
		end
	end
	hit.MouseEnter:Connect(function()
		st.hover = true
		paint()
	end)
	hit.MouseLeave:Connect(function()
		st.hover = false
		paint()
	end)
	hit.Activated:Connect(function()
		if st.enabled then
			open()
		end
	end)
	local e = elem(holder)
	function e:Get()
		return st.value
	end
	function e:Set(v, silent)
		set(v, silent)
	end
	function e:SetOptions(list, keep)
		opts = list
		if not keep then
			st.value = list[1]
		end
		paint()
	end
	function e:SetEnabled(v)
		st.enabled = v and true or false
		paint()
	end
	return e
end

-- ---------- Tabs e ToggleButtons (segmentados) ----------
local function segmented(self, o, set, names, kind, onChange)
	local isTab = kind == "tabs"
	local P = isTab and "tabs/background" or "toggle-button/background"
	local holder = self:_holder(o.Height or (isTab and 22 or 20), o.Width)
	listLayout(holder, 0, true)
	local n = #names
	local btns, current = {}, o.Default or names[1]
	local function paint()
		for name, b in pairs(btns) do
			local sel = name == current
			local path = sel and (P .. "_pressed") or (b.hover and (P .. "_hover") or P)
			setSkin(b.img, path)
			b.txt.TextColor3 = (isTab or sel) and WHITE or BLACK
			b.txt.Position = UDim2.fromOffset(2, sel and 1 or 0)
		end
	end
	for i, name in ipairs(names) do
		local img = skin(holder, P, { Size = UDim2.new(1 / n, 0, 1, 0) })
		img.LayoutOrder = i
		local txt = label(img, tostring(name), {
			X = Enum.TextXAlignment.Center, Size = UDim2.new(1, -4, 1, -3), Position = UDim2.fromOffset(2, 0),
		})
		local hit = hitbox(img)
		local b = { img = img, txt = txt, hover = false }
		btns[name] = b
		hit.MouseEnter:Connect(function()
			b.hover = true
			paint()
		end)
		hit.MouseLeave:Connect(function()
			b.hover = false
			paint()
		end)
		hit.Activated:Connect(function()
			if UIS.TouchEnabled then
				b.hover = false
			end
			if current ~= name then
				current = name
				paint()
				onChange(name)
			end
		end)
	end
	paint()
	local e = elem(holder)
	function e:Get()
		return current
	end
	function e:Set(name, silent)
		current = name
		paint()
		if not silent then
			onChange(name)
		end
	end
	return e, function() return current end
end

function Container:ToggleButtons(o)
	o = o or {}
	local e = segmented(self, o, nil, o.Options or {}, "toggle", function(name)
		spawnCb(o.Callback, name)
	end)
	return e
end

-- Abas: retorna (pages, tabsElement). pages[nome] é um Container.
function Container:Tabs(names, o)
	o = o or {}
	local content = new("Frame", {
		BackgroundTransparency = 1, BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
	})
	local pages, frames = {}, {}
	local active
	local function show(name)
		if active == name then
			return
		end
		if active and frames[active] then
			frames[active].Parent = nil
		end
		active = name
		frames[name].Parent = content
	end
	local strip = segmented(self, { Default = o.Default or names[1], Height = o.Height }, nil, names, "tabs", function(name)
		show(name)
		spawnCb(o.Callback, name)
	end)
	self._n = self._n + 1
	content.LayoutOrder = self._n
	content.Parent = self.Content
	for _, name in ipairs(names) do
		local f = new("Frame", {
			BackgroundTransparency = 1, BorderSizePixel = 0,
			Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
		})
		listLayout(f, Theme.Gap)
		new("UIPadding", { PaddingTop = UDim.new(0, Theme.Gap) }, f)
		frames[name] = f
		pages[name] = newContainer(self, f, 1)
	end
	show(o.Default or names[1])
	function strip:Select(name)
		self:Set(name)
	end
	return pages, strip
end

-- ---------- Card / Row ----------
function Container:Card(o)
	o = o or {}
	self._n = self._n + 1
	local pad = o.Padding or Theme.Pad
	local card = skin(self.Content, "card/" .. (o.Variant or "default") .. "/background", {
		Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = self._n,
	})
	listLayout(card, Theme.Gap)
	new("UIPadding", {
		PaddingTop = UDim.new(0, pad), PaddingBottom = UDim.new(0, pad),
		PaddingLeft = UDim.new(0, pad), PaddingRight = UDim.new(0, pad),
	}, card)
	local c = newContainer(self, card, 1)
	c.Frame = card
	return c
end

function Container:Row(cols)
	self._n = self._n + 1
	local row = new("Frame", {
		BackgroundTransparency = 1, BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = self._n,
	}, self.Content)
	new("UIListLayout", {
		Padding = UDim.new(0, Theme.Gap), SortOrder = Enum.SortOrder.LayoutOrder,
		FillDirection = Enum.FillDirection.Horizontal, Wraps = true,
	}, row)
	local c = newContainer(self, row, cols or 2)
	c.Frame = row
	return c
end

-- ---------- MenuRow (linha de lista com ícone + subtítulo) ----------
function Container:MenuRow(o)
	o = o or {}
	local holder = self:_holder(o.Subtitle and 24 or 20, o.Width)
	local img = skin(holder, "dropdown/option/background")
	local x = 4
	if o.Icon then
		local iconId = o.Icon
		local t = TEX["icon/" .. tostring(o.Icon)]
		if t then
			iconId = asset(t.h) or ""
		end
		new("ImageLabel", {
			BackgroundTransparency = 1, Image = iconId or "", ResampleMode = Enum.ResamplerMode.Pixelated,
			Position = UDim2.fromOffset(4, 4), Size = UDim2.fromOffset(16, 16),
		}, img)
		x = 24
	end
	local title = label(img, o.Title or "", {
		Position = UDim2.fromOffset(x, o.Subtitle and 2 or 0),
		Size = UDim2.new(1, -x - 4, 0, o.Subtitle and 10 or 20),
	})
	local sub
	if o.Subtitle then
		sub = label(img, o.Subtitle, { Color = MUTED, Position = UDim2.fromOffset(x, 12), Size = UDim2.new(1, -x - 4, 0, 10) })
	end
	local hit = hitbox(holder)
	local st = { hover = false, selected = o.Selected and true or false }
	local function paint()
		setSkin(img, st.selected and "dropdown/option/background_selected" or (st.hover and "dropdown/option/background_hover" or "dropdown/option/background"))
	end
	paint()
	hit.MouseEnter:Connect(function()
		st.hover = true
		paint()
	end)
	hit.MouseLeave:Connect(function()
		st.hover = false
		paint()
	end)
	hit.Activated:Connect(function()
		if UIS.TouchEnabled then
			st.hover = false
			paint()
		end
		spawnCb(o.Callback)
	end)
	local e = elem(holder)
	function e:SetSelected(v)
		st.selected = v and true or false
		paint()
	end
	function e:SetTitle(t)
		title.Text = t
	end
	function e:SetSubtitle(t)
		if sub then
			sub.Text = t
		end
	end
	return e
end

-- ============================================================
-- Window
-- ============================================================
local Window = setmetatable({}, { __index = Container })
Window.__index = Window

function OreUI:_connect(signal, fn)
	local c = signal:Connect(fn)
	table.insert(self._conns, c)
	return c
end

function OreUI.new(opts)
	opts = opts or {}
	local self = setmetatable({ _conns = {}, Scale = opts.Scale, Windows = {} }, OreUI)
	local genv = (getgenv and getgenv()) or _G
	if genv.__OreUI_Instance and genv.__OreUI_Instance.Destroy then
		pcall(function()
			genv.__OreUI_Instance:Destroy()
		end)
	end
	genv.__OreUI_Instance = self
	self.Gui = new("ScreenGui", {
		Name = opts.Name or "OreUI",
		ResetOnSpawn = false,
		IgnoreGuiInset = true,
		ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
		DisplayOrder = 999,
	})
	if syn and syn.protect_gui then
		pcall(syn.protect_gui, self.Gui)
	end
	self.Gui.Parent = guiParent()
	return self
end

function OreUI:Destroy()
	for _, c in ipairs(self._conns) do
		pcall(function()
			c:Disconnect()
		end)
	end
	self._conns = {}
	if self.Gui then
		self.Gui:Destroy()
	end
end

function OreUI:Window(o)
	o = o or {}
	local size = o.Size or Vector2.new(300, 200)
	local scale = o.Scale or self.Scale or autoScale(size)
	local frame = new("Frame", {
		Name = "OreWindow", BackgroundTransparency = 1, BorderSizePixel = 0,
		Size = UDim2.fromOffset(size.X, size.Y), AnchorPoint = Vector2.new(0.5, 0.5),
		Position = o.Position or UDim2.fromScale(0.5, 0.5),
	}, self.Gui)
	local uiscale = new("UIScale", { Scale = scale }, frame)
	skin(frame, "card/default/background")

	local win = setmetatable({
		Lib = self, Frame = frame, UIScale = uiscale, Cols = 1, _n = 0,
	}, Window)
	win.Win = win

	-- corpo rolável
	local HH = Theme.HeaderHeight
	local scroll = new("ScrollingFrame", {
		BackgroundTransparency = 1, BorderSizePixel = 0,
		Position = UDim2.fromOffset(1, HH + 1), Size = UDim2.new(1, -2, 1, -(HH + 5)),
		CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 3, ScrollBarImageColor3 = MUTED,
		ScrollingDirection = Enum.ScrollingDirection.Y, ElasticBehavior = Enum.ElasticBehavior.Never,
		VerticalScrollBarInset = Enum.ScrollBarInset.None,
	}, frame)
	listLayout(scroll, Theme.Gap)
	new("UIPadding", {
		PaddingTop = UDim.new(0, 4), PaddingBottom = UDim.new(0, 4),
		PaddingLeft = UDim.new(0, 4), PaddingRight = UDim.new(0, 6),
	}, scroll)
	win.Content = scroll
	win.Scroll = scroll

	-- cabeçalho (barra clara) + arrastar
	local header = skin(frame, "header/background", { Size = UDim2.new(1, 0, 0, HH) })
	local title = label(header, o.Title or "Window", {
		Color = BLACK, X = Enum.TextXAlignment.Center, Font = Theme.TitleFont, TextSize = Theme.TitleSize,
		Position = UDim2.fromOffset(24, 0), Size = UDim2.new(1, -48, 1, -3),
	})
	local drag = hitbox(header)
	local dragging, startMouse, startPos
	drag.InputBegan:Connect(function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
			dragging, startMouse, startPos = true, i.Position, frame.Position
		end
	end)
	self:_connect(UIS.InputChanged, function(i)
		if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
			local d = (i.Position - startMouse) / uiscale.Scale
			frame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
		end
	end)
	self:_connect(UIS.InputEnded, function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
			dragging = false
		end
	end)

	local function iconButton(prefix, anchorX, posX, cb)
		local img = skin(header, prefix .. "/background", {
			AnchorPoint = Vector2.new(anchorX, 0.5), Position = UDim2.new(anchorX, posX, 0.5, -1), Size = UDim2.fromOffset(15, 15),
		})
		local hit = hitbox(img)
		hit.MouseEnter:Connect(function()
			setSkin(img, prefix .. "/background_hover")
		end)
		hit.MouseLeave:Connect(function()
			setSkin(img, prefix .. "/background")
		end)
		hit.MouseButton1Down:Connect(function()
			setSkin(img, prefix .. "/background_pressed")
		end)
		hit.MouseButton1Up:Connect(function()
			setSkin(img, prefix .. "/background")
		end)
		hit.Activated:Connect(function()
			setSkin(img, prefix .. "/background")
			cb()
		end)
		return img
	end

	-- overlay (dropdowns) por cima de tudo
	win.Overlay = new("Frame", { BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 1, 0) }, frame)

	function win:Show()
		frame.Visible = true
	end
	function win:Hide()
		if win._closePopup then
			win._closePopup()
		end
		frame.Visible = false
	end
	function win:Toggle()
		if frame.Visible then
			win:Hide()
		else
			win:Show()
		end
	end
	function win:SetTitle(t)
		title.Text = t
	end
	function win:SetScale(s)
		uiscale.Scale = s
	end
	function win:Destroy()
		frame:Destroy()
	end

	if o.Close ~= false then
		iconButton("button/close", 1, -4, function()
			if o.OnClose then
				spawnCb(o.OnClose)
			end
			win:Hide()
		end)
	end
	if o.Back then
		iconButton("button/back", 0, 4, function()
			spawnCb(o.Back)
		end)
	end

	-- tecla de atalho + botão flutuante (celular)
	if o.Keybind then
		self:_connect(UIS.InputBegan, function(i, gp)
			if not gp and i.KeyCode == o.Keybind then
				win:Toggle()
			end
		end)
	end
	local float = o.FloatButton
	if float == nil then
		float = UIS.TouchEnabled
	end
	if float then
		local fb = new("Frame", {
			BackgroundTransparency = 1, Size = UDim2.fromOffset(24, 24), Position = UDim2.fromOffset(8, 8),
		}, self.Gui)
		new("UIScale", { Scale = math.max(1, scale) }, fb)
		local fimg = skin(fb, "button/secondary/background")
		local ficon = skin(fimg, "icon/menu", { Position = UDim2.fromOffset(4, 3), Size = UDim2.fromOffset(16, 16) })
		local fh = hitbox(fb)
		fh.MouseButton1Down:Connect(function()
			setSkin(fimg, "button/secondary/background_pressed")
		end)
		fh.MouseButton1Up:Connect(function()
			setSkin(fimg, "button/secondary/background")
		end)
		fh.Activated:Connect(function()
			win:Toggle()
		end)
		win.FloatFrame = fb
		local oldDestroy = win.Destroy
		function win:Destroy()
			fb:Destroy()
			oldDestroy(win)
		end
	end

	table.insert(self.Windows, win)
	return win
end

-- ============================================================
-- Notificações
-- ============================================================
function OreUI:Notify(o)
	o = o or {}
	if not self._notify then
		local root = new("Frame", {
			BackgroundTransparency = 1, Size = UDim2.fromOffset(160, 400), AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -8, 0, 8),
		}, self.Gui)
		new("UIScale", { Scale = self.Scale or 1.5 }, root)
		new("UIListLayout", {
			Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder,
			HorizontalAlignment = Enum.HorizontalAlignment.Right,
		}, root)
		self._notify = { root = root, n = 0 }
	end
	local N = self._notify
	N.n = N.n + 1
	local card = skin(N.root, "card/" .. (o.Variant or "raised") .. "/background", {
		Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = N.n,
	})
	listLayout(card, 2)
	new("UIPadding", {
		PaddingTop = UDim.new(0, 6), PaddingBottom = UDim.new(0, 8), PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6),
	}, card)
	if o.Title then
		local t = label(card, o.Title, { Size = UDim2.new(1, 0, 0, 0), Auto = true, Wrap = true, Font = Theme.TitleFont, TextSize = Theme.TitleSize, Color = o.Color or WHITE })
		t.LayoutOrder = 1
	end
	if o.Text then
		local t = label(card, o.Text, { Size = UDim2.new(1, 0, 0, 0), Auto = true, Wrap = true, Color = MUTED })
		t.LayoutOrder = 2
	end
	local hit = new("TextButton", {
		BackgroundTransparency = 1, Text = "", Size = UDim2.new(1, 0, 1, 0), ZIndex = 5,
	}, card)
	local gone = false
	local function dismiss()
		if not gone then
			gone = true
			card:Destroy()
		end
	end
	hit.Activated:Connect(dismiss)
	task.delay(o.Duration or 4, dismiss)
	return { Dismiss = dismiss }
end

-- Ícones embutidos (config, guide, home, menu, remove, reset): MenuRow{Icon = "config"}
function OreUI.GetIcon(name)
	local t = TEX["icon/" .. name]
	return t and asset(t.h) or nil
end

return OreUI
